"use client";

import "./tabs.css";
import { Tabs as BaseTabs } from "@base-ui/react/tabs";
import type React from "react";
import { cn } from "@/lib/cn";

import { TabsContext, useTabsContext } from "./tabs.context";
import { tabsVariants, type TabsVariants } from "./tabs.variants";

export type TabsProps = TabsVariants & React.ComponentProps<typeof BaseTabs.Root>;

export const TabsRoot = ({ children, className, variant, size, isFitted, ...props }: TabsProps) => {
  const slots = tabsVariants({ variant, size, isFitted });

  return (
    <TabsContext.Provider value={{ slots }}>
      <BaseTabs.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseTabs.Root>
    </TabsContext.Provider>
  );
};

export type TabsListProps = React.ComponentProps<typeof BaseTabs.List>;

export const TabsList = ({ className, ...props }: TabsListProps) => {
  const { slots } = useTabsContext();
  return <BaseTabs.List className={cn(slots.list(), className)} {...props} />;
};

export type TabsTabProps = React.ComponentProps<typeof BaseTabs.Tab>;

export const TabsTab = ({ className, ...props }: TabsTabProps) => {
  const { slots } = useTabsContext();
  return <BaseTabs.Tab className={cn(slots.tab(), className)} {...props} />;
};

export type TabsIndicatorProps = React.ComponentProps<typeof BaseTabs.Indicator>;

export const TabsIndicator = ({ className, ...props }: TabsIndicatorProps) => {
  const { slots } = useTabsContext();
  return <BaseTabs.Indicator className={cn(slots.indicator(), className)} {...props} />;
};

export type TabsPanelProps = React.ComponentProps<typeof BaseTabs.Panel>;

export const TabsPanel = ({ className, ...props }: TabsPanelProps) => {
  const { slots } = useTabsContext();
  return <BaseTabs.Panel className={cn(slots.panel(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const tabsVariants = tv({
  slots: {
    root: "tabs",
    list: "tabs__list",
    tab: "tabs__tab",
    indicator: "tabs__indicator",
    panel: "tabs__panel",
  },
  variants: {
    variant: {
      default: {
        list: "tabs__list--default",
        tab: "tabs__tab--default",
        indicator: "tabs__indicator--default",
      },
      pills: {
        list: "tabs__list--pills",
        tab: "tabs__tab--pills",
        indicator: "tabs__indicator--pills",
      },
      underline: {
        list: "tabs__list--underline",
        tab: "tabs__tab--underline",
        indicator: "tabs__indicator--underline",
      },
      segmented: {
        list: "tabs__list--segmented",
        tab: "tabs__tab--segmented",
        indicator: "tabs__indicator--segmented",
      },
      outline: {
        list: "tabs__list--outline",
        tab: "tabs__tab--outline",
        indicator: "tabs__indicator--outline",
      },
      line: {
        list: "tabs__list--line",
        tab: "tabs__tab--line",
        indicator: "tabs__indicator--line",
      },
    },
    size: {
      sm: {
        tab: "tabs__tab--sm",
        panel: "tabs__panel--sm",
      },
      md: {
        tab: "tabs__tab--md",
        panel: "tabs__panel--md",
      },
      lg: {
        tab: "tabs__tab--lg",
        panel: "tabs__panel--lg",
      },
    },
    isFitted: {
      true: {
        list: "tabs__list--fitted",
        tab: "tabs__tab--fitted",
      },
      false: {},
    },
  },
  defaultVariants: {
    variant: "default",
    size: "md",
    isFitted: false,
  },
});

export type TabsVariants = VariantProps<typeof tabsVariants>;

"use client";

import { createContext, useContext } from "react";

import { tabsVariants } from "./tabs.variants";

export type TabsContext = {
  slots: ReturnType<typeof tabsVariants>;
};

export const TabsContext = createContext<TabsContext | null>(null);

export const useTabsContext = () => {
  const context = useContext(TabsContext);
  return context ?? { slots: tabsVariants() };
};

.tabs {
  @apply text-foreground flex w-full max-w-full min-w-0 flex-col;
}

.tabs__list {
  @apply relative flex items-center select-none overflow-x-auto w-full max-w-full flex-nowrap scrollbar-none min-w-0;
}

.tabs__list--default {
  @apply border-b border-border gap-1;
}

.tabs__list--pills {
  @apply bg-muted p-1 rounded-lg gap-1 inline-flex;
}

.tabs__list--underline {
  @apply border-b border-border gap-4;
}

.tabs__list--segmented {
  @apply bg-muted/80 border border-border/60 p-1 rounded-xl gap-1 inline-flex;
}

.tabs__list--outline {
  @apply border border-border p-1 rounded-lg gap-1 bg-background inline-flex;
}

.tabs__list--line {
  @apply border-b border-border/40 gap-2;
}

.tabs__list--fitted {
  @apply w-full;
}

.tabs__tab {
  @apply text-muted-foreground focus-visible:outline-ring inline-flex cursor-pointer items-center justify-center whitespace-nowrap transition-all outline-none focus-visible:outline-2 disabled:pointer-events-none disabled:opacity-50;
}

.tabs__tab--default {
  @apply pb-2 font-medium hover:text-foreground data-active:text-foreground relative;
}

.tabs__tab--pills {
  @apply rounded-md px-3 py-1.5 font-medium hover:text-foreground data-active:bg-background data-active:text-foreground data-active:shadow-xs;
}

.tabs__tab--underline {
  @apply pb-2 border-b-2 border-transparent font-medium hover:text-foreground data-active:border-primary data-active:text-primary;
}

.tabs__tab--segmented {
  @apply rounded-lg px-3 py-1.5 font-medium hover:text-foreground data-active:bg-background data-active:text-foreground data-active:shadow-xs;
}

.tabs__tab--outline {
  @apply rounded-md px-3 py-1.5 font-medium hover:text-foreground data-active:bg-muted data-active:text-foreground;
}

.tabs__tab--line {
  @apply pb-2 font-medium hover:text-foreground data-active:text-primary relative;
}

.tabs__tab--sm {
  @apply text-xs px-2.5 py-1;
}

.tabs__tab--md {
  @apply text-sm px-3.5 py-1.5;
}

.tabs__tab--lg {
  @apply text-base px-4 py-2;
}

.tabs__tab--fitted {
  @apply flex-1 grow text-center min-w-0;
}

.tabs__indicator {
  @apply absolute z-0;
}

.tabs__indicator--default {
  @apply bottom-0 h-0.5 bg-primary transition-all duration-200;
}

.tabs__indicator--pills {
  @apply bg-background rounded-md shadow-xs transition-all duration-200;
}

.tabs__indicator--underline {
  @apply bottom-0 h-0.5 bg-primary transition-all duration-200;
}

.tabs__indicator--segmented {
  @apply bg-background rounded-lg shadow-xs transition-all duration-200;
}

.tabs__indicator--outline {
  @apply bg-muted rounded-md transition-all duration-200;
}

.tabs__indicator--line {
  @apply bottom-0 h-0.5 bg-primary transition-all duration-200;
}

.tabs__panel {
  @apply focus-visible:outline-ring mt-2 outline-none focus-visible:outline-2 w-full max-w-full min-w-0 overflow-x-auto;
}

.tabs__panel--sm {
  @apply py-2 text-xs;
}

.tabs__panel--md {
  @apply py-3 text-sm;
}

.tabs__panel--lg {
  @apply py-4 text-base;
}

import { TabsIndicator, TabsList, TabsPanel, TabsRoot, TabsTab } from "./tabs";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/tabs/content.md
 */
export const Tabs = Object.assign(TabsRoot, {
  Indicator: TabsIndicator,
  List: TabsList,
  Panel: TabsPanel,
  Root: TabsRoot,
  Tab: TabsTab,
  indicator: TabsIndicator,
  list: TabsList,
  panel: TabsPanel,
  root: TabsRoot,
  tab: TabsTab,
});

export { TabsIndicator, TabsList, TabsPanel, TabsRoot, TabsTab };

export type {
  TabsIndicatorProps,
  TabsListProps,
  TabsPanelProps,
  TabsProps,
  TabsTabProps,
} from "./tabs";
export { TabsContext, useTabsContext } from "./tabs.context";
export { type TabsVariants, tabsVariants } from "./tabs.variants";
